task.spawn(function()
    while RUNNING do
        pcall(function()
            local hrs = math.max(1 / 60, (os.clock() - S.t0) / 3600)
            setText(UI.s1, string.format(__T["Wins %s · Level %s · Rebirths %s"], M.fmt(M.num("Wins")), M.fmt(M.num("Level")), M.fmt(M.num("Rebirths"))))
            setText(UI.s2, __T["Doing: "] .. S.task)
            setText(UI.s3, string.format(__T["+%s wins (%s/h) · %s runs"], M.fmt(S.wins), M.fmt(S.wins / hrs), M.fmt(S.runs)))
            local g = (os.clock() - S.msgAt < 8 and S.msg ~= "") and S.msg or ((os.clock() - S.gmsgAt < 8 and S.gmsg ~= "") and ("Game: " .. S.gmsg) or (S.kicked and "Disconnected from server" or ""))
            setText(UI.s4, g)
            local n = F.pickStage()
            local pad = F.padFor(n)
            setText(UI.wf, string.format(__T["Stage %d · %s wins per run%s"], n, pad and M.fmt(pad.wins) or "?", S.spdMul < 1 and string.format(__T[" · speed %d%%"], math.floor(S.spdMul * 100)) or ""))
            local st = F.bestStation()
            setText(UI.tr, string.format(__T["Station: %s · Arms %s · XP %s"], st and tostring(st.Name) or "-", M.fmt(M.num("ArmCount")), M.fmt(M.num("XP"))))
            local nxt = M.num("ArmatureUnlocked") + 1
            local cost = (SHOP.Costs or {})[nxt]
            local reb = M.num("Rebirths")
            local need = (REB.FirstLevel or 10) + (REB.LevelStep or 10) * reb
            setText(UI.up, string.format(__T["Armature %d/%d%s\nRebirth at level %d (x%.1f XP)"], nxt - 1, #(SHOP.Costs or {}), cost and (__T[" · next "] .. M.fmt(cost) .. __T[" wins"]) or __T[" · maxed"], need, 1 + (REB.MultiplierStep or 0.5) * reb))
            local now = Workspace:GetServerTimeNow()
            local dl = M.num("DailyTime") + 86400 - now
            local sl = M.num("StayReadyAt") - now
            setText(UI.rw, string.format(__T["Daily: %s · 2x gift: %s"], dl <= 0 and __T["ready"] or M.eta(math.floor(dl)), sl <= 0 and __T["ready"] or M.eta(math.floor(sl))))
        end)
        task.wait(0.5)
    end
end)
onClean(function() pcall(function() Library:Unload() end) end)
pcall(function()
    if isfile and isfile("COMBO_WICK_SPIDERARM/settings/auto.json") then SaveManager:Load("auto") else SaveManager:LoadAutoloadConfig() end
end)
do
    local pending = false
    local function queue()
        if pending or not RUNNING then return end
        pending = true
        task.delay(1.5, function() pending = false; if RUNNING then pcall(function() SaveManager:Save("auto") end) end end)
    end
    local function skip(k) k = tostring(k); return k == "MenuKeybind" or k:find("^ThemeManager") or k:find("^SaveManager") or k:find("Color") or k == "FeedbackMsg" or k == "FeedbackType" end
    task.delay(2, function()
        for k, t in pairs(Toggles) do if not skip(k) then pcall(function() local prev = t.Changed t:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
        for k, o in pairs(Opt) do if not skip(k) then pcall(function() local prev = o.Changed o:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
    end)
end
function UI.center()
    pcall(function()
        local sg = Library.ScreenGui
        local m = sg and sg:FindFirstChild("Main")
        if not m then return end
        m.AnchorPoint = Vector2.zero
        for _ = 1, 3 do
            local vs, sz, cur = sg.AbsoluteSize, m.AbsoluteSize, m.AbsolutePosition
            local tx, ty = math.max(0, math.floor((vs.X - sz.X) / 2)), math.max(0, math.floor((vs.Y - sz.Y) / 2))
            local k = (m.Size.X.Offset > 0 and sz.X / m.Size.X.Offset) or 1
            if math.abs(cur.X - tx) < 2 and math.abs(cur.Y - ty) < 2 then break end
            m.Position = UDim2.new(m.Position.X.Scale, m.Position.X.Offset + (tx - cur.X) / k, m.Position.Y.Scale, m.Position.Y.Offset + (ty - cur.Y) / k)
            RunService.Heartbeat:Wait()
        end
    end)
end
for _, d in ipairs({ 1, 3, 6 }) do task.delay(d, UI.center) end
notify(__T["Loaded"])

end
